CREATE TABLE "usuario" (
  "rut" varchar(10) PRIMARY KEY,
  "nombres" varchar(100) NOT NULL,
  "apellidos" varchar(100) NOT NULL,
  "telefono" varchar(25) NOT NULL,
  "correo" varchar(254),
  "password" varchar(255),
  "precauciones" text NOT NULL DEFAULT ''
);

CREATE TABLE "rol" (
  "id_rol" smallint PRIMARY KEY,
  "nombre" varchar(20) UNIQUE NOT NULL
);

CREATE TABLE "usuario_rol" (
  "rut" varchar(10) NOT NULL,
  "id_rol" smallint NOT NULL,
  PRIMARY KEY ("rut", "id_rol")
);

CREATE TABLE "especialidad" (
  "id_especialidad" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "nombre" varchar(100) UNIQUE NOT NULL,
  "activa" boolean NOT NULL DEFAULT true
);

CREATE TABLE "usuario_especialidad" (
  "rut" varchar(10) NOT NULL,
  "id_especialidad" bigint NOT NULL,
  PRIMARY KEY ("rut", "id_especialidad")
);

CREATE TABLE "tipo_precio" (
  "id_tipo_precio" smallint PRIMARY KEY,
  "nombre" varchar(20) UNIQUE NOT NULL
);

CREATE TABLE "servicio" (
  "id_servicio" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_especialidad" bigint NOT NULL,
  "id_tipo_precio" smallint NOT NULL,
  "nombre" varchar(150) NOT NULL,
  "descripcion" text NOT NULL DEFAULT '',
  "precio" integer NOT NULL,
  "precio_oferta" integer,
  "activo" boolean NOT NULL DEFAULT true,
  CHECK (precio >= 0),
  CHECK (precio_oferta IS NULL OR (precio_oferta >= 0 AND precio_oferta < precio))
);

CREATE TABLE "anuncio" (
  "id_anuncio" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "titulo" varchar(150) NOT NULL,
  "contenido" text NOT NULL,
  "imagen_url" text,
  "orden" integer NOT NULL DEFAULT 0,
  "activo" boolean NOT NULL DEFAULT true,
  CHECK (orden >= 0)
);

CREATE TABLE "dia_semana" (
  "id_dia" smallint PRIMARY KEY,
  "nombre" varchar(10) UNIQUE NOT NULL,
  CHECK (id_dia BETWEEN 1 AND 7)
);

CREATE TABLE "horario_trabajo" (
  "id_horario" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "rut_especialista" varchar(10) NOT NULL,
  "id_dia" smallint NOT NULL,
  "hora_inicio" time NOT NULL,
  "hora_fin" time NOT NULL,
  CHECK (hora_fin > hora_inicio)
);

CREATE TABLE "origen_reserva" (
  "id_origen" smallint PRIMARY KEY,
  "nombre" varchar(20) UNIQUE NOT NULL
);

CREATE TABLE "estado_reserva" (
  "id_estado" smallint PRIMARY KEY,
  "nombre" varchar(20) UNIQUE NOT NULL
);

CREATE TABLE "reserva" (
  "id_reserva" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "rut_cliente" varchar(10) NOT NULL,
  "rut_especialista" varchar(10) NOT NULL,
  "id_especialidad" bigint NOT NULL,
  "id_origen" smallint NOT NULL,
  "id_estado" smallint NOT NULL,
  "fecha_hora_inicio" timestamptz NOT NULL,
  "fecha_hora_fin" timestamptz NOT NULL,
  "motivo" text NOT NULL DEFAULT '',
  "indicaciones" text NOT NULL DEFAULT '',
  "retencion_hasta" timestamptz,
  "id_evento_google" text,
  CHECK (fecha_hora_fin > fecha_hora_inicio)
);

CREATE TABLE "medio_pago" (
  "id_medio" smallint PRIMARY KEY,
  "nombre" varchar(30) UNIQUE NOT NULL
);

CREATE TABLE "pago" (
  "id_pago" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_reserva" bigint UNIQUE NOT NULL,
  "id_medio" smallint NOT NULL,
  "monto" integer NOT NULL DEFAULT 5000,
  "referencia_transaccion" varchar(150),
  CHECK (monto > 0),
  CHECK (id_medio <> 1 OR (referencia_transaccion IS NOT NULL AND length(trim(referencia_transaccion)) > 0))
);

CREATE TABLE "atencion" (
  "id_atencion" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  "id_reserva" bigint UNIQUE NOT NULL,
  "servicio_realizado" varchar(200) NOT NULL,
  "detalle" text NOT NULL,
  "observaciones" text NOT NULL DEFAULT '',
  CHECK (length(trim(servicio_realizado)) > 0),
  CHECK (length(trim(detalle)) > 0)
);

CREATE UNIQUE INDEX ON "horario_trabajo" ("rut_especialista", "id_dia", "hora_inicio", "hora_fin");

CREATE UNIQUE INDEX ON "pago" ("id_medio", "referencia_transaccion");

ALTER TABLE "usuario_rol" ADD FOREIGN KEY ("rut") REFERENCES "usuario" ("rut") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "usuario_rol" ADD FOREIGN KEY ("id_rol") REFERENCES "rol" ("id_rol") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "usuario_especialidad" ADD FOREIGN KEY ("rut") REFERENCES "usuario" ("rut") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "usuario_especialidad" ADD FOREIGN KEY ("id_especialidad") REFERENCES "especialidad" ("id_especialidad") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "servicio" ADD FOREIGN KEY ("id_especialidad") REFERENCES "especialidad" ("id_especialidad") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "servicio" ADD FOREIGN KEY ("id_tipo_precio") REFERENCES "tipo_precio" ("id_tipo_precio") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "horario_trabajo" ADD FOREIGN KEY ("rut_especialista") REFERENCES "usuario" ("rut") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "horario_trabajo" ADD FOREIGN KEY ("id_dia") REFERENCES "dia_semana" ("id_dia") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reserva" ADD FOREIGN KEY ("rut_cliente") REFERENCES "usuario" ("rut") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reserva" ADD FOREIGN KEY ("rut_especialista", "id_especialidad") REFERENCES "usuario_especialidad" ("rut", "id_especialidad") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reserva" ADD FOREIGN KEY ("id_origen") REFERENCES "origen_reserva" ("id_origen") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "reserva" ADD FOREIGN KEY ("id_estado") REFERENCES "estado_reserva" ("id_estado") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pago" ADD FOREIGN KEY ("id_medio") REFERENCES "medio_pago" ("id_medio") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "pago" ADD FOREIGN KEY ("id_reserva") REFERENCES "reserva" ("id_reserva") DEFERRABLE INITIALLY IMMEDIATE;

ALTER TABLE "atencion" ADD FOREIGN KEY ("id_reserva") REFERENCES "reserva" ("id_reserva") DEFERRABLE INITIALLY IMMEDIATE;
